}

// rows: [{file, transcript, ...}], files: [{id, path}] -> {results: [{row, file_id, status}], orphans: [id]}
function matchRows(rows, files) {
  const finfo = files.map(f => Object.assign({ id: f.id }, splitPath(f.path)));
  const index = (keyf) => {
