    }
    if (chosen) {
      used.add(chosen.id);
      res[i] = { row: i, file_id: chosen.id, status };
    } else {
      res[i] = { row: i, file_id: null, status: status || 'MISSING' };
    }
  });

  return { results: res, orphans: finfo.filter(f => !used.has(f.id)).map(f => f.id) };
}

